<script setup>
import {ref,reactive,onMounted,computed} from 'vue'
import {api,session} from '../api'
import Icon from '../components/Icon.vue'
import PasswordDialog from '../components/PasswordDialog.vue'
const form=reactive({name:session.user?.name||'',phone:session.user?.phone||''}),student=ref(null),busy=ref(false),error=ref(''),notice=ref(''),passwordOpen=ref(false)
const role=computed(()=>({admin:'Administrador',teacher:'Docente',student:'Estudiante'}[session.user?.role]))
const initials=computed(()=>session.user?.name?.split(' ').slice(0,2).map(x=>x[0]).join(''))
onMounted(async()=>{try{const result=await api('/profile');student.value=result.student;Object.assign(form,{name:result.user.name,phone:result.user.phone||''})}catch(e){error.value=e.message}})
async function save(){busy.value=true;error.value='';notice.value='';try{const result=await api('/profile',{method:'PUT',body:{name:form.name,phone:form.phone}});session.user=result.user;Object.assign(form,{name:result.user.name,phone:result.user.phone||''});notice.value=result.message}catch(e){error.value=Object.values(e.errors||{}).flat().join(' ')||e.message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">TU ESPACIO PERSONAL</span><h1>Mi perfil<span class="heading-dot">.</span></h1><p>Tu información y la seguridad de tu cuenta, en un solo lugar.</p></div></div><v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{error}}</v-alert><v-alert v-if="notice" type="success" variant="tonal" class="mb-5">{{notice}}</v-alert><section class="profile-grid"><article class="panel profile-summary"><span class="profile-avatar">{{initials}}</span><h2>{{session.user?.name}}</h2><span class="evaluation-chip">{{role}}</span><p>{{session.user?.email}}</p><div v-if="student" class="profile-academic"><strong>{{student.student_code}}</strong><p>{{student.career}}</p></div><div class="profile-security"><Icon name="ShieldCheck"/><strong>Acceso protegido</strong><p>{{session.user?.role==='admin'?'Tu acceso administrativo utiliza correo y contraseña.':'Tu cuenta utiliza contraseña y Google Authenticator.'}}</p></div></article><article class="panel profile-details"><div class="panel-heading"><div><h2>Información personal</h2><p>Mantén tus datos de contacto actualizados.</p></div><Icon name="UserRound"/></div><form @submit.prevent="save" class="profile-form"><v-text-field v-model="form.name" label="Nombre completo" autocomplete="name" maxlength="150" required/><v-text-field :model-value="session.user?.email" label="Correo electrónico" type="email" readonly hint="Para cambiar tu correo, contacta al administrador." persistent-hint/><v-text-field v-model="form.phone" label="Teléfono" autocomplete="tel" maxlength="25" class="mt-5"/><v-btn color="primary" type="submit" :loading="busy">Guardar cambios</v-btn></form><div class="profile-password"><div><h3>Contraseña</h3><p>Actualiza tu contraseña cuando lo necesites.</p></div><v-btn variant="tonal" color="primary" @click="passwordOpen=true"><Icon name="KeyRound" :size="17" class="mr-2"/>Cambiar contraseña</v-btn></div></article></section><PasswordDialog v-model="passwordOpen"/></template>
